select jsonb_build_object('entries_total',(select count(*) from public.event_competition_entries),'entries_by_status',(select coalesce(jsonb_object_agg(status,n),'{}'::jsonb) from (select status,count(*) n from public.event_competition_entries group by 1) s),'entry_changes',(select count(*) from public.event_competition_entry_changes),'heat_entries',(select count(*) from public.event_competition_heat_entries)) as r;
